rows=[]
for p in sorted((b/'receipts').glob('*.json')):
 r=json.loads(p.read_text());raw=root/'data/raw/formal_development_20261007_v1'/r['run_id']/'outputs';physical='sumo.log' in r['output_manifest']
 role='FIX02_CONTROL' if r['run_id'].endswith('A03') and r['treatment'] in ('T1','T2') else ('OPEN_NEUTRALITY_BASELINE' if r['status']=='COMPLETED' and r['treatment']=='OPEN' else 'PRESERVED_TECHNICAL_OR_DIAGNOSTIC')
 rows.append({'run_id':r['run_id'],'status':r['status'],'role':role,'worker_attempt':True,'physical_SUMO_evidence':physical,'wall_s':r['wall_s'],'payload_bytes':r['output_bytes'],'actual_raw_bytes':sum(x.stat().st_size for x in raw.rglob('*') if x.is_file()),'receipt':str(p.relative_to(root)),'receipt_sha256':sha(p),'return_code':r['return_code'],'stop_reason':r['stop_reason']})
